    <section class="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div><p class="text-xs font-black uppercase tracking-[.18em] text-emerald-600">Start session</p><h2 class="mt-1 text-xl font-black text-slate-900">Configure check-in</h2></div><form method="POST" action="<?php echo e(route('attendance.start')); ?>" id="start-attendance-form" class="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-6"><?php echo csrf_field(); ?><select name="course_id" required class="rounded-xl border-slate-300 xl:col-span-2"><option value="">Select course</option><?php $__currentLoopData = $courses; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $course): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($course->id); ?>" <?php if(old('course_id')==$course->id): echo 'selected'; endif; ?>><?php echo e($course->code); ?> — <?php echo e($course->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><label class="text-xs font-bold text-slate-500">Check-in window<input type="number" name="check_in_window" min="1" max="180" value="<?php echo e(old('check_in_window',30)); ?>" class="mt-1 w-full rounded-xl border-slate-300"></label><label class="text-xs font-bold text-slate-500">Late threshold<input type="number" name="late_threshold" min="0" max="180" value="<?php echo e(old('late_threshold',15)); ?>" class="mt-1 w-full rounded-xl border-slate-300"></label><input type="hidden" name="latitude" id="session-latitude"><input type="hidden" name="longitude" id="session-longitude"><input type="hidden" name="geofence_radius" value="100"><button type="button" id="capture-location" class="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-2 text-sm font-bold text-emerald-700">Use current location</button><button class="rounded-xl bg-emerald-700 px-4 py-2 text-sm font-black text-white">Start session</button><p id="location-message" class="hidden text-xs text-slate-500 xl:col-span-6"></p></form></section>
    <div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><?php $__empty_1 = true; $__currentLoopData = $sessions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $session): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><article class="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-lg"><div class="flex items-start justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-wide text-emerald-600"><?php echo e($session->course->code); ?></p><h2 class="mt-1 font-black text-slate-900"><?php echo e($session->course->name); ?></h2></div><span class="rounded-full px-3 py-1 text-xs font-bold <?php echo e($session->status==='active'?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-600'); ?>"><?php echo e(str($session->status)->headline()); ?></span></div><div class="mt-5 grid grid-cols-2 gap-3"><div class="rounded-xl bg-slate-50 p-3"><p class="text-[10px] font-bold uppercase text-slate-400">Started</p><p class="mt-1 text-sm font-bold text-slate-700"><?php echo e($session->started_at->format('M j · H:i')); ?></p></div><div class="rounded-xl bg-slate-50 p-3"><p class="text-[10px] font-bold uppercase text-slate-400">Records</p><p class="mt-1 text-sm font-bold text-slate-700"><?php echo e($session->records_count); ?></p></div></div><a href="<?php echo e(route('attendance.session',$session)); ?>" class="mt-5 block rounded-xl bg-slate-900 px-4 py-2.5 text-center text-sm font-black text-white">Open session</a></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="md:col-span-2 xl:col-span-3 rounded-[2rem] border border-dashed border-slate-300 bg-white p-14 text-center"><h2 class="text-xl font-black text-slate-900">No sessions yet</h2><p class="mt-2 text-sm text-slate-500">Start an attendance session for one of your assigned courses.</p></div><?php endif; ?></div>
